<script setup lang="ts">
import{ref,onMounted}from'vue';import{locale}from'../i18n';const props=defineProps<{businessId:string}>();const profile=ref<any>(null),slug=ref(''),reason=ref(''),busy=ref(false),message=ref('');const tr=(a:string,b:string)=>locale.value==='id'?a:b;
onMounted(async()=>{try{const r=await fetch('/platform/business-domain?id='+encodeURIComponent(props.businessId),{credentials:'same-origin',signal:AbortSignal.timeout(15000)});if(r.ok)profile.value=await r.json();}catch{message.value=tr('Alamat belum dapat dimuat.','Address unavailable.');}});
async function save(){if(busy.value)return;busy.value=true;message.value='';try{const r=await fetch('/platform/business-domain',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''},body:JSON.stringify({business_id:props.businessId,slug:slug.value,reason:reason.value,version:Number(profile.value.version),operation_id:crypto.randomUUID()}),signal:AbortSignal.timeout(20000)});const d=await r.json();if(!r.ok)throw Error(d.code??String(r.status));profile.value={...profile.value,...d};slug.value='';message.value=tr('Alamat diubah; pemberitahuan masuk antrean email.','Address changed; notification queued.');}catch(e){message.value=tr('Belum berhasil. Periksa nama dan verifikasi keamanan.','Unable to complete. Check name and security verification.')+' · '+String(e);}finally{busy.value=false;}}
</script>
<template><section v-if="profile" class="domain-panel"><h3>{{tr('Alamat bisnis permanen','Permanent business address')}}</h3><a v-if="profile.url" :href="profile.url" target="_blank" rel="noopener">{{profile.url}}</a><p>{{tr('Hanya pemilik platform dapat mengganti alamat. Nama lama tetap dikarantina dan pemilik bisnis menerima email.','Only the platform owner can rename an address. The old name remains quarantined and the business owner is emailed.')}}</p><form @submit.prevent="save"><label>{{tr('Nama subdomain baru','New subdomain')}}<input v-model="slug" pattern="[a-z][a-z0-9-]{2,39}" minlength="3" maxlength="40" required/></label><label>{{tr('Alasan perubahan','Reason')}}<input v-model="reason" maxlength="300" required/></label><button :disabled="busy">{{busy?tr('Menyimpan…','Saving…'):tr('Ubah & beri tahu pemilik','Rename & notify owner')}}</button></form><p role="status">{{message}}</p></section></template>
<style scoped>.domain-panel{padding:20px;border:1px solid #E9EBFF;border-radius:16px;background:#FFFFFF;color:#1B1B39;font:16px/1.6 system-ui}.domain-panel label{display:grid;margin:12px 0;gap:8px}.domain-panel input{padding:12px;border:1px solid #99B7FC;border-radius:10px;font:inherit}.domain-panel button{padding:12px;background:#3965FA;color:#FFFFFF;border:0;border-radius:10px;font:600 16px system-ui}.domain-panel a{color:#3965FA}</style>
